// Package flatbuffers implements a thin passthrough codec for already-encoded
// FlatBuffer payloads. The universal Codec contract speaks `any`, but
// FlatBuffers is a schema-driven format whose typed access lives in caller
// code (generated by `flatc`). This package therefore registers a codec that
// round-trips raw FlatBuffer bytes — Marshal hands back the buffer the caller
// already has; Unmarshal publishes the buffer to the caller's target without
// parsing it. Real schema-typed reads stay in the caller's generated
// accessors.
//
// The codec uses no third-party dependency. The only validation is the
// 4-byte root-offset header required by the FlatBuffers wire format.
package flatbuffers

import (
	"encoding/binary"
	"slices"

	"github.com/kitsunium/sdk/internal/core/codec"
	"github.com/kitsunium/sdk/internal/kernel/errs"
)

// flatBuffersHeaderBytes is the size of the root-offset header (uint32).
// Every well-formed FlatBuffer starts with this 4-byte little-endian value.
const flatBuffersHeaderBytes int = 4

// maxFlatBuffersBytes caps the Unmarshal / Marshal input size for untrusted
// payloads. FlatBuffers schemas tend to carry larger blobs than JSON
// (embedded media, tensor weights, …), so 64 MiB is the chosen ceiling for
// the SDK's passthrough path — generous enough for realistic schema payloads
// while still bounding memory-exhaustion (CWE-400) blast radius. Callers
// that legitimately need bigger buffers can bypass the codec and feed the
// generated accessors directly.
const maxFlatBuffersBytes int = 64 << 20

// PromotionMagic is the synthetic little-endian uint32 header stamped by
// the facade promotion path in pkg/v1/codec/promote.go when it wraps a
// non-FlatBuffer value in flatbuffers-shaped bytes. 0x80000001 is a
// deliberately invalid root offset (a real root offset points INTO the
// buffer, never past it AND never the high bit set), so a flatc-
// generated reader fails predictably on these bytes — only the SDK
// itself recognises and unwraps them.
//
// Exported so promote.go can stamp the same value without a duplicated
// magic-number constant.
const PromotionMagic uint32 = 0x80000001

// Package-level state: the codec singleton plus the hoisted MIME /
// extension tables.
var (
	//: register the singleton and expose it as a typed package var.
	Codec codec.Codec = codec.Register(&flatbuffersCodec{})

	//: MIME table hoisted; the second alias documents the passthrough
	//: nature for consumers that resolve via Content-Type.
	mimeTypes = []string{"application/x-flatbuffers", "application/octet-stream+flatbuffers"}

	//: extension table hoisted. ".bin" is ambiguous on disk — see CLAUDE.md.
	extensions = []string{".fbs", ".bin"}
)

// flatbuffersCodec is the concrete passthrough Codec for FlatBuffers.
type flatbuffersCodec struct{}

// New returns the FlatBuffers passthrough codec singleton.
func New() codec.Codec {
	//: stateless — one singleton is enough for the whole process.
	return Codec
}

// Name implements codec.Codec.
func (*flatbuffersCodec) Name() string {
	//: canonical identifier.
	return "flatbuffers"
}

// MIMETypes lists every MIME alias.
func (*flatbuffersCodec) MIMETypes() []string {
	//: hand back a defensive copy so callers cannot mutate package state.
	return slices.Clone(mimeTypes)
}

// Extensions lists every file extension.
func (*flatbuffersCodec) Extensions() []string {
	//: hand back a defensive copy so callers cannot mutate package state.
	return slices.Clone(extensions)
}

// Marshal resolves v to its already-encoded FlatBuffer bytes and returns
// them verbatim. No copy is performed in the happy path; the caller owns
// the returned slice. Promotion-marked bytes (header == PromotionMagic)
// skip the full validation step — we just produced them in promote.go
// so re-checking the size + header is wasted work on the hot path.
func (*flatbuffersCodec) Marshal(v any) (encoded []byte, err error) {
	//: promotion-sentinel fast-path — recognise our own wrapper bytes
	//: and skip resolveSourceBytes + validateBuffer (size cap still
	//: applies via the comparison below).
	if b, ok := v.([]byte); ok && len(b) >= flatBuffersHeaderBytes &&
		binary.LittleEndian.Uint32(b) == PromotionMagic &&
		len(b) <= maxFlatBuffersBytes {
		//: caller bytes verbatim — we own the lifetime via promote.go.
		return b, nil
	}
	//: extract a payload via the shared resolver so Marshal/Append agree.
	src, rerr := resolveSourceBytes(v)
	//: surface the typed rejection immediately.
	if rerr != nil {
		//: nothing to hand back.
		return nil, rerr
	}
	//: validate the buffer shape before returning it.
	if verr := validateBuffer(src); verr != nil {
		//: same rejection for both Marshal and Append paths.
		return nil, verr
	}
	//: passthrough — return the caller's bytes unchanged.
	return src, nil
}

// Unmarshal publishes the (validated) FlatBuffer payload to v. Either the
// caller passes a `*[]byte` (zero-copy reference) or a value implementing
// BytesAcceptor (the codec hands the slice off via SetBytes).
func (*flatbuffersCodec) Unmarshal(data []byte, v any) error {
	//: validate the buffer shape before touching the target.
	if verr := validateBuffer(data); verr != nil {
		//: surface the FLATBUFFERS_TRUNCATED sentinel directly.
		return verr
	}
	//: fast-path: caller passed *[]byte — publish the slice by reference.
	if dst, ok := v.(*[]byte); ok && dst != nil {
		//: zero-copy reference; caller shares ownership of data.
		*dst = data
		//: nothing else to do.
		return nil
	}
	//: structured-target path: caller implements BytesAcceptor.
	if acc, ok := v.(BytesAcceptor); ok {
		//: hand the buffer off; the implementation chooses copy semantics.
		acc.SetBytes(data)
		//: nothing else to do.
		return nil
	}
	//: anything else is a programming error for this codec.
	return errs.Wrap(nil, errs.WrapParams{
		Code:    CodeFlatbuffersBadTarget,
		Reason:  "FLATBUFFERS_BAD_TARGET",
		Public:  "FlatBuffers codec requires a *[]byte or BytesAcceptor target",
		Private: "service/codec/flatbuffers.Unmarshal: target is not *[]byte and does not implement BytesAcceptor",
	})
}

// Append resolves the source bytes the same way Marshal does and appends
// them onto dst. Implements the optional codec.Appender interface so hot-
// path callers can stitch a FlatBuffer payload into a larger framed
// envelope without an intermediate allocation.
func (c *flatbuffersCodec) Append(dst []byte, v any) (appended []byte, err error) {
	//: delegate to Marshal so the wrap/error contract has a single source.
	src, merr := c.Marshal(v)
	//: surface any resolution / validation failure without touching dst.
	if merr != nil {
		//: return the untouched buffer plus the wrapped error.
		return dst, merr
	}
	//: append the resolved bytes onto the caller's buffer.
	return append(dst, src...), nil
}

// resolveSourceBytes extracts the FlatBuffer payload from v. Either v is
// `[]byte` itself or v implements BytesProvider. Anything else surfaces the
// FLATBUFFERS_UNSUPPORTED_TYPE sentinel.
func resolveSourceBytes(v any) (src []byte, err error) {
	//: fast-path: caller already handed us the raw bytes.
	if b, ok := v.([]byte); ok {
		//: passthrough verbatim.
		return b, nil
	}
	//: structured-source path: caller implements BytesProvider.
	if prov, ok := v.(BytesProvider); ok {
		//: extract the payload; the implementation owns lifetime semantics.
		return prov.Bytes(), nil
	}
	//: anything else is a programming error for this codec.
	return nil, errs.Wrap(nil, errs.WrapParams{
		Code:    CodeFlatbuffersBadType,
		Reason:  "FLATBUFFERS_BAD_TYPE",
		Public:  "FlatBuffers codec requires []byte or a BytesProvider value",
		Private: "service/codec/flatbuffers.Marshal: argument is not []byte and does not implement BytesProvider",
	})
}

// validateBuffer enforces the minimum FlatBuffer wire-format shape: the
// 4-byte root offset header must be present, and the buffer MUST NOT exceed
// the codec's CWE-400 ceiling.
func validateBuffer(data []byte) error {
	//: minimum size — a FlatBuffer without the root offset is unparseable.
	if len(data) < flatBuffersHeaderBytes {
		//: surface the typed truncation sentinel.
		return errs.Wrap(nil, errs.WrapParams{
			Code:    CodeFlatbuffersTruncated,
			Reason:  "FLATBUFFERS_TRUNCATED",
			Public:  "FlatBuffers buffer is truncated",
			Private: "service/codec/flatbuffers.validateBuffer: len(data) < flatBuffersHeaderBytes",
		}, errs.Int("len", len(data)), errs.Int("min", flatBuffersHeaderBytes))
	}
	//: maximum size — bound the memory-exhaustion blast radius.
	if len(data) > maxFlatBuffersBytes {
		//: same sentinel; the size policy is documented on the const.
		return errs.Wrap(nil, errs.WrapParams{
			Code:    CodeFlatbuffersTruncated,
			Reason:  "FLATBUFFERS_TRUNCATED",
			Public:  "FlatBuffers buffer exceeds size limit",
			Private: "service/codec/flatbuffers.validateBuffer: len(data) > maxFlatBuffersBytes",
		}, errs.Int("len", len(data)), errs.Int("max", maxFlatBuffersBytes))
	}
	//: buffer is acceptable — caller may proceed.
	return nil
}
